# without shared context, a naive host call looks like this
result = await email_client.call_tool("send_reminder", {
    "to": "team@example.com",
    # the new meeting time from the calendar server never made it here
})

class SharedContext:
    def __init__(self):
        self.facts = {}       # keyed facts learned from any server
        self.decisions = {}   # choices made earlier in the conversation
        self.history = []     # ordered log of what was learned and when

    def remember(self, key, value, source):
        self.facts[key] = value
        self.history.append({
            "key": key,
            "value": value,
            "source": source,
        })

    def get(self, key, default=None):
        return self.facts.get(key, default)
